options.getOption:
let timeData = [],
  Blower1Values = [], Blower2Values = [], Blower3Values = [],
  Blower4Values = [], Blower5Values = [],
  Incomer1Values = [], Incomer2Values = [],
  LightingValues = [], PDB1Values = [], PDB2Values = [],
  PMCC1Incomer1Values = [], PMCC2Incomer1Values = [], PMCC3Incomer1Values = [],
  PMCC1Incomer2Values = [], PMCC2Incomer2Values = [], PMCC3Incomer2Values = [],
  TorrentValues = [];

context.panel.data.series.forEach((s) => {
  if (!timeData.length) {
    const timeField = s.fields.find(f => f.name === 'date' || f.name === 'time' || f.name === 'month_date' || f.name === 'Time');
    if (timeField) timeData = timeField.values;
  }

  if (s.refId === 'A') {
    const f = s.fields.find(f => f.name === 'Blower1');
    if (f) Blower1Values = f.values;
  } else if (s.refId === 'B') {
    const f = s.fields.find(f => f.name === 'Blower2');
    if (f) Blower2Values = f.values;
  } else if (s.refId === 'C') {
    const f = s.fields.find(f => f.name === 'Blower3');
    if (f) Blower3Values = f.values;
  } else if (s.refId === 'D') {
    const f = s.fields.find(f => f.name === 'Blower4');
    if (f) Blower4Values = f.values;
  } else if (s.refId === 'E') {
    const f = s.fields.find(f => f.name === 'Blower5');
    if (f) Blower5Values = f.values;
  } else if (s.refId === 'F') {
    const f = s.fields.find(f => f.name === 'Incomer1');
    if (f) Incomer1Values = f.values;
  } else if (s.refId === 'G') {
    const f = s.fields.find(f => f.name === 'Incomer2');
    if (f) Incomer2Values = f.values;
  } else if (s.refId === 'H') {
    const f = s.fields.find(f => f.name === 'PDB1');
    if (f) PDB1Values = f.values;
  } else if (s.refId === 'I') {
    const f = s.fields.find(f => f.name === 'PDB2');
    if (f) PDB2Values = f.values;
  } else if (s.refId === 'J') {
    const f = s.fields.find(f => f.name === 'Lighting');
    if (f) LightingValues = f.values;
  } else if (s.refId === 'K') {
    const f = s.fields.find(f => f.name === 'Torrent');
    if (f) TorrentValues = f.values;
  } else if (s.refId === 'L') {
    const f = s.fields.find(f => f.name === 'PMCC1-Incomer1');
    if (f) PMCC1Incomer1Values = f.values;
  } else if (s.refId === 'M') {
    const f = s.fields.find(f => f.name === 'PMCC3-Incomer1');
    if (f) PMCC3Incomer1Values = f.values;
  } else if (s.refId === 'N') {
    const f = s.fields.find(f => f.name === 'PMCC2-Incomer1');
    if (f) PMCC2Incomer1Values = f.values;
  } else if (s.refId === 'O') {
    const f = s.fields.find(f => f.name === 'PMCC1-Incomer2');
    if (f) PMCC1Incomer2Values = f.values;
  } else if (s.refId === 'P') {
    const f = s.fields.find(f => f.name === 'PMCC2-Incomer2');
    if (f) PMCC2Incomer2Values = f.values;
  } else if (s.refId === 'Q') {
    const f = s.fields.find(f => f.name === 'PMCC3-Incomer2');
    if (f) PMCC3Incomer2Values = f.values;
  }
});

let PMCC1Values = [], PMCC2Values = [], PMCC3Values = [];
let totalMonthlyConsumption = [];

for (let i = 0; i < timeData.length; i++) {
  const pmcc1 = (PMCC1Incomer1Values[i] || 0) + (PMCC1Incomer2Values[i] || 0);
  const pmcc2 = (PMCC2Incomer1Values[i] || 0) + (PMCC2Incomer2Values[i] || 0);
  const pmcc3 = (PMCC3Incomer1Values[i] || 0) + (PMCC3Incomer2Values[i] || 0);

  PMCC1Values.push(pmcc1);
  PMCC2Values.push(pmcc2);
  PMCC3Values.push(pmcc3);

  let total = 0;
  total += Blower1Values[i] || 0;
  total += Blower2Values[i] || 0;
  total += Blower3Values[i] || 0;
  total += Blower4Values[i] || 0;
  total += Blower5Values[i] || 0;
  total += Incomer1Values[i] || 0;
  total += Incomer2Values[i] || 0;
  total += LightingValues[i] || 0;
  total += PDB1Values[i] || 0;
  total += PDB2Values[i] || 0;
  total += pmcc1;
  total += pmcc2;
  total += pmcc3;
  totalMonthlyConsumption.push(total);
}

const averageTotalMonthlyConsumption =
  totalMonthlyConsumption.length > 0
    ? totalMonthlyConsumption.reduce((sum, value) => sum + value, 0) / totalMonthlyConsumption.length
    : 0;

const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
const formattedMonths = timeData.map(d => {
  const date = new Date(d);
  return `${monthNames[date.getUTCMonth()]} ${date.getUTCFullYear()}`;
});

const customColors = {
  'Blower1': '#1f77b4',
  'Blower2': '#ff7f0e',
  'Blower3': '#2ca02c',
  'Blower4': '#d62728',
  'Blower5': '#9467bd',
  'Incomer1': '#e377c2',
  'Incomer2': '#7f7f7f',
  'Lighting': '#8c564b',
  'PDB1': '#bcbd22',
  'PDB2': '#17becf',
  'PMCC1': '#aec7e8',
  'PMCC2': '#ffbb78',
  'PMCC3': '#98df8a',
  'Torrent': '#f7b6d2'
};

return {
  title: {
    text: `Average Monthly Consumption: {value|${averageTotalMonthlyConsumption.toFixed(2)} kwh/month}`,
    left: 'center',
    bottom: 0,
    textStyle: {
      fontSize: 20,
      rich: {
        value: {
          color: '#00ff00',
          fontSize: 24,
          fontWeight: 'bold'
        }
      }
    }
  },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'cross' }
  },
  legend: {
    data: ['Blower1', 'Blower2', 'Blower3', 'Blower4', 'Blower5',
      'Incomer1', 'Incomer2', 'Lighting', 'PDB1', 'PDB2',
      'PMCC1', 'PMCC2', 'PMCC3', 'Torrent']
  },
  grid: {
    left: '5%',
    right: '4%',
    bottom: '10%',
    containLabel: true
  },
  xAxis: {
    type: 'category',
    data: formattedMonths,
    axisLabel: {
      fontSize: 12
    }
  },
  yAxis: {
    type: 'value',
    name: 'Monthly Power Consumption',
    nameLocation: 'middle',
    nameGap: 90,
    nameTextStyle: {
      fontSize: 12,
      align: 'center',
      verticalAlign: 'middle',
    }
  },
  color: Object.values(customColors),
  series: [
    { name: 'Blower1', type: 'bar', stack: 'total', data: Blower1Values, itemStyle: { color: customColors['Blower1'] } },
    { name: 'Blower2', type: 'bar', stack: 'total', data: Blower2Values, itemStyle: { color: customColors['Blower2'] } },
    { name: 'Blower3', type: 'bar', stack: 'total', data: Blower3Values, itemStyle: { color: customColors['Blower3'] } },
    { name: 'Blower4', type: 'bar', stack: 'total', data: Blower4Values, itemStyle: { color: customColors['Blower4'] } },
    { name: 'Blower5', type: 'bar', stack: 'total', data: Blower5Values, itemStyle: { color: customColors['Blower5'] } },
    { name: 'Incomer1', type: 'bar', stack: 'total', data: Incomer1Values, itemStyle: { color: customColors['Incomer1'] } },
    { name: 'Incomer2', type: 'bar', stack: 'total', data: Incomer2Values, itemStyle: { color: customColors['Incomer2'] } },
    { name: 'Lighting', type: 'bar', stack: 'total', data: LightingValues, itemStyle: { color: customColors['Lighting'] } },
    { name: 'PDB1', type: 'bar', stack: 'total', data: PDB1Values, itemStyle: { color: customColors['PDB1'] } },
    { name: 'PDB2', type: 'bar', stack: 'total', data: PDB2Values, itemStyle: { color: customColors['PDB2'] } },
    { name: 'PMCC1', type: 'bar', stack: 'total', data: PMCC1Values, itemStyle: { color: customColors['PMCC1'] } },
    { name: 'PMCC2', type: 'bar', stack: 'total', data: PMCC2Values, itemStyle: { color: customColors['PMCC2'] } },
    { name: 'PMCC3', type: 'bar', stack: 'total', data: PMCC3Values, itemStyle: { color: customColors['PMCC3'] } },
    { name: 'Torrent', type: 'line', data: TorrentValues, itemStyle: { color: customColors['Torrent'] }, lineStyle: { color: customColors['Torrent'] } }
  ]
};

