options.getOption:
let timeData = [];
let inFlowMeter = [];
let outFlowMeter = [];

context.panel.data.series.forEach((s) => {
  if (s.refId === 'In Flow Meter Reading') {
    timeData = s.fields.find(f => f.name === 'Time' || f.name === 'date' || f.name === 'time')?.values ?? [];
    inFlowMeter = s.fields.find(f => f.name === 'In Flow Meter Reading')?.values ?? [];
  }

  if (s.refId === 'Out Flow Meter Reading') {
    outFlowMeter = s.fields.find(f => f.name === 'Out Flow Meter Reading')?.values ?? [];
  }
});

// Format dates as Month Year (e.g., 'Apr 2026')
const monthNames = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const formattedMonths = timeData.map(d => {
  const date = new Date(d);
  return `${monthNames[date.getUTCMonth()]} ${date.getUTCFullYear()}`;
});

return {
  tooltip: {
    trigger: 'axis',
    axisPointer: {
      type: 'cross',
    },
    formatter: function (params) {
      let tooltipText = `${params[0].axisValueLabel}<br/>`;
      params.forEach((item) => {
        let value = item.data === '-' ? '-' : `${item.data.toLocaleString()} m³`;
        tooltipText += `${item.marker} ${item.seriesName}: ${value}<br/>`;
      });
      return tooltipText;
    },
  },
  legend: {
    data: ['Flow Meter(In)', 'Flow Meter(Out)'],
    top: '2%'
  },
  grid: {
    left: '5%',
    right: '4%',
    bottom: '10%',
    containLabel: true
  },
  xAxis: {
    type: 'category',
    data: formattedMonths,
    axisLabel: {
      fontSize: 12
    }
  },
  yAxis: {
    type: 'value',
    axisLabel: {
      formatter: function (val) {
        return `${val.toLocaleString()} m³`;
      },
    },
  },
  series: [
    {
      name: 'Flow Meter(In)',
      type: 'line',
      data: inFlowMeter.map(value => (value == null || value <= 0 ? "-" : value))
    },
    {
      name: 'Flow Meter(Out)',
      type: 'line',
      data: outFlowMeter.map(value => (value == null || value <= 0 ? "-" : value))
    },
  ]
};

